contract InvMutTest is Test {
    VaultAdapter c;
    function setUp() public { c = new VaultAdapter(); }
    function testRegression_property() public {
        bytes32 expectedSlot = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
        bytes32 result;
        try c.proxiableUUID() returns (bytes32 val) {
            result = val;
        } catch {
            result = bytes32(0);
        }
        assertTrue(result == expectedSlot, "proxiableUUID should return the implementation slot");
    }
}
